async function invokeFunction(name,body){
 const {data,error}=await db.functions.invoke(name,{body});if(error){let message=error.message;try{message=(await error.context.json()).error||message;}catch{}throw Error(message);}if(!data||data.error)throw Error(data?.error||'Empty server response.');return data;
}
async function load(){
 if(state.demo){state.profile=demoData.profile;state.jobs=demoData.jobs;state.applications=demoData.applications;state.candidates=demoData.candidates;render();return;}
 const {data:{user},error:authError}=await db.auth.getUser();if(authError||!user)throw Error('Session expired. Please sign in again.');
 const {data:p,error}=await db.from('profiles').select('*').eq('id',user.id).single();if(error)throw error;if(!p.active){await db.auth.signOut();throw Error('Your account is paused. Contact your coordinator.');}state.profile=p;state.admin=p.role==='admin';
 if(p.must_change_password){render();return;}
 const results=await Promise.all([db.from('jobs').select('*').order('created_at',{ascending:false}),db.from('applications').select('*').order('created_at',{ascending:false}),state.admin?db.from('profiles').select('*').eq('role','candidate').order('created_at',{ascending:false}):Promise.resolve({data:[],error:null}),state.admin?db.from('job_contacts').select('*'):Promise.resolve({data:[],error:null})]);
 for(const r of results)if(r.error)throw r.error;
 [state.jobs,state.applications,state.candidates]=results.map(r=>r.data||[]);for(const j of state.jobs)Object.assign(j,(results[3].data||[]).find(c=>c.job_id===j.id)||{});render();
}
async function api(body){if(state.demo)throw Error('This action needs a live Supabase connection.');const {data,error}=await db.functions.invoke('account-admin',{body});if(error){let message=error.message;try{message=(await error.context.json()).error||message;}catch{}throw Error(message);}if(data.error)throw Error(data.error);return data;}
function accountForm(id){const p=state.candidates.find(p=>p.id===id);showModal(dialogHead(id?'Reset password':'Create candidate')+`<form id="candidate-form" data-id="${id||''}"><p class="small muted">${state.lang==='hi'?'अस्थायी पासवर्ड को उम्मीदवार से सुरक्षित रूप से साझा करें। यह सहेजा या ईमेल नहीं होगा।':'Share the temporary password privately with the candidate. It is not stored in the app or sent by email.'}</p>${id?`<p><strong>${esc(p.full_name)}</strong> · ${esc(p.email)}</p>`:field('Full name','full_name','','text','required maxlength="120"')+field('Email address','email','','email','required')}${field('Temporary password','password','','password','required minlength="12" autocomplete="new-password"')}<label class="check" style="margin-top:14px"><input type="checkbox" name="verified" required>${id?E('Identity verified before reset'):(state.lang==='hi'?'मैंने उम्मीदवार की पात्रता, सहमति और ईमेल की पुष्टि की है।':'I have verified community eligibility, consent, and the candidate’s email ownership.')}</label><div class="form-actions">${button(id?'Reset password':'Create candidate','','','type="submit"')}</div></form>`);}
async function viewCV(path){if(!path)throw Error('No CV was submitted.');if(state.demo){toast('CV preview is available after Supabase setup.');return;}const {data,error}=await db.storage.from('cvs').createSignedUrl(path,60);if(error)throw error;showModal(dialogHead('View CV')+`<p>${state.lang==='hi'?'यह निजी लिंक एक मिनट में समाप्त हो जाएगा।':'This private download link expires in one minute.'}</p><a class="btn" href="${esc(data.signedUrl)}" target="_blank" rel="noopener noreferrer">${E('View CV')} ↗</a>`);}
function candidateDetails(id){const p=state.candidates.find(x=>x.id===id);if(!p)return;showModal(dialogHead('My profile')+`<h3>${esc(p.full_name)}</h3><p>${esc(p.email)} · ${esc(p.phone||'—')}</p><p>${esc(p.city||'—')} · ${p.experience??0} ${state.lang==='hi'?'वर्ष':'years'}</p><p>${E('Preferred roles')}: ${esc(p.roles||'—')}</p><p>${E('Skills')}: ${esc((p.skills||[]).join(', ')||'—')}</p><p>${E('Preferred cities')}: ${esc(p.cities||'—')}</p><p>${E('Expected CTC (₹ lakh/year)')}: ${p.expected_ctc??'—'}</p><p>${E('Joining availability')}: ${E(p.notice_period||'—')}</p><p>${E('Employment status')}: ${E(p.employment_status||'—')}</p>${p.urgent?'<div class="notice">Urgent support requested</div>':''}${p.cv_path?button('View CV','candidate-cv','secondary',`data-id="${p.id}"`):''}`);}
function reviewApplication(id){const a=state.applications.find(x=>x.id===id);if(!a)return;const p=a.profile_snapshot||{};showModal(dialogHead('Applications')+`<h3>${esc(p.full_name)}</h3><p>${esc(p.email)} · ${esc(p.phone)}</p><p>${E('Skills')}: ${esc((p.skills||[]).join(', '))}</p><p>${E('Experience')}: ${esc(p.experience??'—')}</p><p>${E('Expected CTC (₹ lakh/year)')}: ${esc(p.expected_ctc??'—')}</p><p>${E('Preferred cities')}: ${esc(p.cities||'—')}</p><div class="notice">${E('Email delivery is not configured. Applications are saved for admin review.')}</div>${a.cv_path?button('View CV','application-cv','secondary',`data-id="${a.id}"`):''}<form id="status-form" data-id="${a.id}" style="margin-top:20px">${select('Status','status',a.status==='withdrawn'?['withdrawn']:['applied','under_review','interview','selected','not_selected','withdrawn'],a.status)}<div class="form-actions">${button('Save changes','','','type="submit"')}</div></form>`);}
async function action(name,id){
 switch(name){
 case 'close':closeModal();return;
 case 'demo':state.demo=true;demoData=seedDemo();state.admin=false;state.page='jobs';await load();return;
 case 'switch-role':state.admin=!state.admin;state.page='jobs';render();return;
 case 'logout':if(!state.demo)await db.auth.signOut();state.demo=false;state.profile=null;state.admin=false;state.search='';state.page='jobs';closeModal();renderAuth();return;
 case 'help':if(!state.profile)showModal(dialogHead('Help with access')+`<p>${E('Your account is created and approved by an admin.')}</p><p>${esc(cfg.supportContact||t('Please contact your community coordinator.'))}</p>`);else{state.page='help';render();}return;
 case 'go-profile':state.page='profile';render();return;
 case 'go-jobs':state.page='jobs';render();return;
 case 'view-job':detailJob(id);return;
 case 'new-job':jobEditor();return;
 case 'edit-job':jobEditor(id);return;
 case 'new-candidate':accountForm();return;
 case 'reset-candidate':accountForm(id);return;
 case 'candidate-details':candidateDetails(id);return;
 case 'own-cv':await viewCV(state.profile.cv_path);return;
 case 'candidate-cv':await viewCV(state.candidates.find(p=>p.id===id)?.cv_path);return;
 case 'application-cv':await viewCV(state.applications.find(a=>a.id===id)?.cv_path);return;
 case 'review-application':reviewApplication(id);return;
 case 'toggle-candidate':{
 const p=state.candidates.find(p=>p.id===id);if(state.demo)p.active=!p.active;else await api({action:'set-active',user_id:id,active:!p.active});await load();toast('Saved');return;}
 case 'withdraw':{
 if(!confirm(state.lang==='hi'?'यह आवेदन वापस लें?':'Withdraw this application?'))return;
 if(state.demo)state.applications.find(a=>a.id===id).status='withdrawn';else{const {error}=await db.rpc('withdraw_application',{application_id:id});if(error)throw error;}await load();return;}
 case 'password-dialog':showModal(dialogHead('Change password')+`<form id="password-form">${field('Current password','current','','password','required autocomplete="current-password"')}${field('New password','password','','password','required minlength="12" autocomplete="new-password"')}${field('Confirm password','confirm','','password','required minlength="12" autocomplete="new-password"')}<p class="small muted">${E('Passwords must have at least 12 characters.')}</p>${button('Save password','','','type="submit"')}</form>`);return;
 case 'analyse-cv':
 case 'read-cv':{
 const file=document.querySelector('#cv-file')?.files[0];if(!file)throw Error(t('Select a CV first.'));
 const ai=name==='analyse-cv';if(ai&&!document.querySelector('#ai-consent').checked)throw Error(t('Choose a CV and give AI consent first.'));
 if(ai&&state.demo)throw Error(t('Claude analysis is available after Supabase setup. Use Read without AI in the demo.'));
 const form=document.querySelector('#profile-form'),el=document.querySelector('#cv-status');el.textContent=state.lang==='hi'?'CV का विश्लेषण हो रहा है…':'Analysing your CV…';
 try{
  const result=await readResume(file,{allowEmptyText:ai});
  if(!form.elements.phone.value&&result.phone)form.elements.phone.value=result.phone;
  if(ai){const body={consent:true,language:state.lang,kind:result.ext==='pdf'?'pdf':'text'};
   if(result.ext==='pdf')body.pdf_base64=await resumeBase64(file);else body.text=result.text;
   const response=await invokeFunction('resume-analyse',body);el.textContent=t('Check these suggestions. Nothing is saved until you save your profile.');resumeReview(response.analysis,resumeFileKey(file));
  }else{form.elements.primary_skills.value=mergeSkillLists(splitSkills(form.elements.primary_skills.value),result.skills).slice(0,20).join(', ');el.textContent=t('Contact details and skills are suggestions. Please check them before saving.');}
 }catch(e){el.textContent=t('CV reading failed. You can still save your profile manually.');throw e;}return;
 }

 }
}
async function submit(form){const data=new FormData(form),get=k=>String(data.get(k)||'').trim(),num=k=>get(k)===''?null:Number(get(k)),yes=k=>data.has(k);
 if(form.id==='login-form'){
  if(!db)throw Error('Configure Supabase in config.js first, or explore the demo.');const {data:result,error}=await db.auth.signInWithPassword({email:get('email'),password:data.get('password')});if(error)throw error;session=result.session;await load();
 }else if(form.id==='password-form'){
  if(state.demo)throw Error('Password changes are disabled in the demo.');if(data.get('password')!==data.get('confirm'))throw Error('Passwords do not match.');if(String(data.get('password')).length<12)throw Error('Passwords must have at least 12 characters.');if(data.get('password')===data.get('current'))throw Error('Choose a different password.');await api({action:'change-password',current_password:data.get('current'),password:data.get('password')});closeModal();await db.auth.signOut({scope:'local'});state.profile=null;state.admin=false;renderAuth();toast(state.lang==='hi'?'पासवर्ड सहेजा गया। नए पासवर्ड से लॉगिन करें।':'Password saved. Sign in with your new password.');
 }else if(form.id==='resume-review-form'){
  const file=document.querySelector('#cv-file')?.files[0];if(!pendingResume||!file||pendingResume.fileKey!==resumeFileKey(file))throw Error('The selected CV changed. Please analyse it again.');
  const primary=splitSkills(get('primary_skills')),other=splitSkills(get('other_skills'));if(primary.length>20||other.length>30||mergeSkillLists(primary,other).some(x=>x.length>80))throw Error('Please shorten the skill lists.');
  const target=document.querySelector('#profile-form');target.elements.primary_skills.value=primary.join(', ');target.elements.other_skills.value=other.join(', ');
  if(get('roles'))target.elements.roles.value=get('roles');if(num('experience')!==null)target.elements.experience.value=num('experience');
  target.dataset.resumeSummary=pendingResume.analysis.summary;
  document.querySelector('#profile-summary').innerHTML=`<div class="notice green" style="margin-top:18px"><strong>${E('AI summary')}</strong><p style="margin:8px 0 0">${esc(pendingResume.analysis.summary)}</p></div>`;
  pendingResume=null;closeModal();toast('Check these suggestions. Nothing is saved until you save your profile.');
 }else if(form.id==='profile-form'){
  const primary=splitSkills(get('primary_skills')),other=splitSkills(get('other_skills'));
  const p={full_name:get('full_name'),phone:get('phone').replace(/[\s()-]/g,''),city:state.profile.city||get('cities').split(',')[0].trim(),roles:get('roles'),primary_skills:primary,other_skills:other,skills:mergeSkillLists(primary,other),experience:num('experience'),current_ctc:num('current_ctc'),expected_ctc:num('expected_ctc'),cities:get('cities'),urgent:yes('urgent'),consent:yes('consent')};
  if(form.dataset.resumeSummary!==undefined)p.resume_summary=form.dataset.resumeSummary;
  validateProfile(p);if(!p.consent)throw Error('Please confirm consent.');
  const file=document.querySelector('#cv-file').files[0];let uploaded=null;
  if(file){const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','docx'].includes(ext)||file.size>2*1024*1024)throw Error('Use a PDF or DOCX CV of up to 2 MB.');if(!state.demo){uploaded=`${state.profile.id}/${crypto.randomUUID()}.${ext}`;const {error}=await db.storage.from('cvs').upload(uploaded,file,{contentType:ext==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.wordprocessingml.document',upsert:false});if(error)throw error;p.cv_path=uploaded;p.cv_name=file.name;}else{p.cv_name=file.name;p.cv_path=null;}}
  if(state.demo)Object.assign(demoData.profile,p);else{const {error}=await db.from('profiles').update(p).eq('id',state.profile.id);if(error){if(uploaded)await db.storage.from('cvs').remove([uploaded]);throw error;}}await load();toast('Profile saved.');
 }else if(form.id==='job-form'){
  const existing=state.jobs.find(x=>x.id===form.dataset.id)||{};
  const j={title:get('title'),company:get('company'),city:get('city'),category:existing.category||get('title').slice(0,100),skills:splitSkills(get('skills')),mandatory_skills:data.has('mandatory_skills')?splitSkills(get('mandatory_skills')):(existing.mandatory_skills||[]),experience_min:num('experience_min'),experience_max:data.has('experience_max')?num('experience_max'):(existing.experience_max??null),salary_min:num('salary_min'),salary_max:num('salary_max'),work_mode:existing.work_mode||'Office',employment_type:existing.employment_type||'Full-time',description:get('description'),closes_on:get('closes_on')||null,status:get('status'),freshers:existing.freshers??((num('experience_min')??0)===0),career_break:existing.career_break??false,source_verified:yes('source_verified')};
  const source=existing.source||get('company');validateJob({...j,recipient_email:get('recipient_email')});
  if(state.demo){j.recipient_email=get('recipient_email');j.source=source;if(form.dataset.id)Object.assign(state.jobs.find(x=>x.id===form.dataset.id),j);else state.jobs.unshift({...j,id:crypto.randomUUID(),created_at:new Date().toISOString()});}
  else{const {data:jobId,error}=await db.rpc('save_job',{job_id:form.dataset.id||null,payload:j,contact:{recipient_email:get('recipient_email'),source}});if(error)throw error;}
  closeModal();state.search='';state.city='';state.mode='';state.page='jobs';await load();toast('Job saved.');
 }else if(form.id==='apply-form'){
  try{validateProfile(state.profile);}catch{throw Error(t('Please save your profile with a mobile number, preferred roles and skills before applying.'));}
  const id=form.dataset.id;if(state.demo){if(state.applications.some(a=>a.job_id===id))throw Error('You have already applied.');state.applications.unshift({id:crypto.randomUUID(),job_id:id,candidate_id:state.profile.id,profile_snapshot:structuredClone(state.profile),cv_path:null,job_snapshot:structuredClone(state.jobs.find(j=>j.id===id)),status:'applied',created_at:new Date().toISOString(),email_status:'disabled'});}else{const {error}=await db.rpc('apply_to_job',{target_job:id});if(error)throw error;}
  closeModal();await load();toast('Application saved');
 }else if(form.id==='candidate-form'){
  if(state.demo){if(form.dataset.id)toast('Password changes are disabled in the demo.');else{if(state.candidates.some(p=>p.email===get('email')))throw Error('This email already exists.');state.candidates.unshift({...seedDemo().profile,id:crypto.randomUUID(),full_name:get('full_name'),email:get('email'),skills:[],roles:'',phone:'',city:'',cv_path:null,cv_name:null,must_change_password:true});toast('Saved');}}else await api({action:form.dataset.id?'reset-password':'create-candidate',user_id:form.dataset.id||undefined,email:get('email'),full_name:get('full_name'),password:data.get('password'),identity_verified:yes('verified')});
  form.reset();closeModal();await load();toast('Saved');
 }else if(form.id==='status-form'){
  if(state.demo)state.applications.find(a=>a.id===form.dataset.id).status=get('status');else{const {error}=await db.rpc('set_application_status',{application_id:form.dataset.id,next_status:get('status')});if(error)throw error;}closeModal();await load();toast('Saved');
 }
}
async function guarded(fn,buttonEl){if(state.busy)return;state.busy=true;if(buttonEl)buttonEl.disabled=true;try{await fn();}catch(e){console.error(e);toast(e.message||'Something went wrong. Please try again.',true);}finally{state.busy=false;if(buttonEl?.isConnected)buttonEl.disabled=false;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-page]');if(!el)return;if(el.dataset.action==='close'){e.preventDefault();closeModal();return;}if(el.dataset.page){state.page=el.dataset.page;render();return;}if(el.type==='submit')return;e.preventDefault();guarded(()=>action(el.dataset.action,el.dataset.id),el);});
document.addEventListener('submit',e=>{e.preventDefault();guarded(()=>submit(e.target),e.submitter);});
document.addEventListener('change',e=>{if(e.target.id==='cv-file'){pendingResume=null;const f=document.querySelector('#profile-form');f.dataset.resumeSummary='';document.querySelector('#profile-summary').innerHTML='';document.querySelector('#cv-status').textContent='';}if(e.target.id==='language'){state.lang=e.target.value;localStorage.setItem('sj-language',state.lang);document.documentElement.lang=state.lang;closeModal();render();}if(e.target.id==='show-password'){const field=document.querySelector('#login-form input[name="password"]');field.type=e.target.checked?'text':'password';}if(e.target.id==='job-city'||e.target.id==='job-mode'){state[e.target.id==='job-city'?'city':'mode']=e.target.value;document.querySelector('#jobs-list').innerHTML=jobCards();}});
document.addEventListener('input',e=>{if(e.target.id==='job-search'){state.search=e.target.value;document.querySelector('#jobs-list').innerHTML=jobCards();}if(e.target.id==='candidate-search')document.querySelector('#candidate-list').innerHTML=candidateRows(e.target.value);});
async function init(){document.documentElement.lang=state.lang;renderAuth();if(cfg.supabaseUrl&&cfg.supabaseAnonKey){try{const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.49.8/+esm');db=createClient(cfg.supabaseUrl,cfg.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});const {data,error}=await db.auth.getSession();if(error)throw error;session=data.session;if(session)await load();}catch(e){state.profile=null;renderAuth();toast(e.message||'Unable to connect to Supabase.',true);}}}
init();
